Q: Trigger a function from a widget to a State object A: <p>I had exactly your problem: the click on a Fab needed to call a method on a child widget. My solution is similar to the accepted answer, but instead of using a <code>Stream</code>, it uses a <code>ChangeNotifier</code>.</p>
<p>Please note that the following example is simple (a fab which increases a counter) and therefore you could have achieved the same result using a <code>ListenableBuilder</code>.</p>
<pre class="lang-dart prettyprint-override"><code>import 'package:flutter/material.dart';

void main() {
  MyListener myListener = MyListener();
  runApp(
    MaterialApp(
      home: Scaffold(
        body: MyCounter(myListener),
        floatingActionButton: IconButton(
          onPressed: () =&gt; myListener.trigger(),
          icon: Text(&quot;+&quot;),
        ),
      ),
    ),
  );
}

class MyListener extends ChangeNotifier {
  void trigger() {
    notifyListeners();
  }
}

class MyCounter extends StatefulWidget {
  final MyListener listener;

  const MyCounter(this.listener, {super.key});

  @override
  State&lt;StatefulWidget&gt; createState() =&gt; _MyState();
}

class _MyState extends State&lt;MyCounter&gt; {
  int n = 0;

  void update(){
    setState(() =&gt; n++,);
  }

  @override
  void initState() {
    super.initState();
    //Don't write .addListener(() =&gt; update()), otherwise you'll add an anonymous function
    widget.listener.addListener(update);
  }

  @override
  void didUpdateWidget(covariant MyCounter oldWidget) {
    super.didUpdateWidget(oldWidget);

    //Check if the listener is the same as before
    if(oldWidget.listener != widget.listener){
      //Don't write .removeListener(() =&gt; update()), otherwise you'll remove an anonymous function
      oldWidget.listener.removeListener(update);

      //Don't write .addListener(() =&gt; update()), otherwise you'll add an anonymous function
      widget.listener.addListener(update);
    }
  }

  @override
  void dispose() {
    super.dispose();
    //Don't write .removeListener(() =&gt; update()), otherwise you'll remove an anonymous function
    widget.listener.removeListener(update);
  }

  @override
  Widget build(BuildContext context) {
    return Center(child: Text(n.toString()));
  }
}
</code></pre>
